INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000805', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'What does SQL stand for?', '["Structured Query Language", "Simple Query Language", "Standard Query Language", "Sequential Query Language"]', 'Structured Query Language', 'SQL is the standard language for managing and manipulating relational databases.', 'active'),
('60000000-0000-0000-0000-000000000806', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'Which SQL clause is used to filter results?', '["WHERE", "FILTER", "HAVING", "CONDITION"]', 'WHERE', 'The WHERE clause filters rows based on specified conditions.', 'active'),
('60000000-0000-0000-0000-000000000807', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'What is the purpose of SELECT statement?', '["Retrieve data from database", "Insert data", "Update data", "Delete data"]', 'Retrieve data from database', 'SELECT retrieves data from one or more tables in a database.', 'active'),
('60000000-0000-0000-0000-000000000808', '50000000-0000-0000-0000-000000000057', 'simple', 'code_mcq', 'What does this SQL do? SELECT * FROM employees;', '["Retrieves all columns from employees", "Retrieves specific columns", "Counts employees", "Filters employees"]', 'Retrieves all columns from employees', 'The asterisk (*) selects all columns from the employees table.', 'active'),
('60000000-0000-0000-0000-000000000809', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What is the difference between WHERE and HAVING?', '["WHERE filters rows, HAVING filters groups", "WHERE filters groups, HAVING filters rows", "Both filter rows", "Both filter groups"]', 'WHERE filters rows, HAVING filters groups', 'WHERE filters rows before grouping, HAVING filters groups after grouping.', 'active'),
('60000000-0000-0000-0000-000000000810', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What does GROUP BY do?', '["Groups rows with same values", "Sorts rows", "Filters rows", "Combines tables"]', 'Groups rows with same values', 'GROUP BY groups rows that have the same values in specified columns.', 'active'),
('60000000-0000-0000-0000-000000000811', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What is a subquery?', '["Query within another query", "Nested query", "Inner query", "All of the above"]', 'All of the above', 'A subquery is a query nested inside another SQL query.', 'active'),
('60000000-0000-0000-0000-000000000812', '50000000-0000-0000-0000-000000000057', 'intermediate', 'code_mcq', 'What does JOIN do in SQL?', '["Combines rows from multiple tables", "Filters tables", "Sorts tables", "Groups tables"]', 'Combines rows from multiple tables', 'JOIN combines columns from one or more tables based on related columns.', 'active'),
('60000000-0000-0000-0000-000000000813', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What is a correlated subquery?', '["Subquery referencing outer query", "Independent subquery", "Simple subquery", "Nested query"]', 'Subquery referencing outer query', 'Correlated subqueries reference columns from the outer query.', 'active'),
('60000000-0000-0000-0000-000000000814', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What are window functions?', '["Perform calculations across rows", "Aggregate functions", "Scalar functions", "Table functions"]', 'Perform calculations across rows', 'Window functions perform calculations across a set of table rows related to the current row.', 'active'),
('60000000-0000-0000-0000-000000000815', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What is CTE (Common Table Expression)?', '["Temporary named result set", "Temporary table", "View", "Stored procedure"]', 'Temporary named result set', 'CTE is a temporary result set that can be referenced within SELECT, INSERT, UPDATE, or DELETE statements.', 'active'),
('60000000-0000-0000-0000-000000000816', '50000000-0000-0000-0000-000000000057', 'expert', 'code_mcq', 'What does WITH RECURSIVE enable?', '["Recursive queries", "Recursive CTEs", "Hierarchical queries", "All of the above"]', 'All of the above', 'WITH RECURSIVE enables recursive common table expressions for hierarchical data.', 'active'),
('60000000-0000-0000-0000-000000000817', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What are materialized views?', '["Precomputed query results", "Virtual tables", "Temporary tables", "Indexed views"]', 'Precomputed query results', 'Materialized views store query results physically for faster access.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000818', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'What is an index in SQL?', '["Performance optimization structure", "Table structure", "Data structure", "Query structure"]', 'Performance optimization structure', 'Indexes speed up data retrieval by providing quick lookup paths.', 'active'),
('60000000-0000-0000-0000-000000000819', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'What is a primary key?', '["Unique identifier for table rows", "Foreign key", "Index key", "Constraint key"]', 'Unique identifier for table rows', 'Primary key uniquely identifies each row in a table and cannot be NULL.', 'active'),
('60000000-0000-0000-0000-000000000820', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'What is a foreign key?', '["Links tables together", "Primary key in another table", "Referential constraint", "All of the above"]', 'All of the above', 'Foreign key establishes a relationship between two tables by referencing a primary key.', 'active'),
('60000000-0000-0000-0000-000000000821', '50000000-0000-0000-0000-000000000058', 'simple', 'code_mcq', 'What does EXPLAIN ANALYZE provide?', '["Query execution plan", "Query analysis", "Performance metrics", "All of the above"]', 'All of the above', 'EXPLAIN ANALYZE shows the query execution plan with actual runtime statistics.', 'active'),
('60000000-0000-0000-0000-000000000822', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What is query optimization?', '["Improving query performance", "Rewriting queries", "Using indexes", "All of the above"]', 'All of the above', 'Query optimization involves improving SQL query performance through various techniques.', 'active'),
('60000000-0000-0000-0000-000000000823', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What are composite indexes?', '["Indexes on multiple columns", "Multiple indexes", "Compound indexes", "Both A and C"]', 'Both A and C', 'Composite indexes involve multiple columns and are also called compound indexes.', 'active'),
('60000000-0000-0000-0000-000000000824', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What is the N+1 query problem?', '["Multiple round trips to database", "Inefficient queries", "Performance issue", "All of the above"]', 'All of the above', 'N+1 problem occurs when an application makes N+1 database queries instead of 1.', 'active'),
('60000000-0000-0000-0000-000000000825', '50000000-0000-0000-0000-000000000058', 'intermediate', 'code_mcq', 'What does LATERAL JOIN enable?', '["Reference earlier tables in FROM", "Cross join", "Self join", "Outer join"]', 'Reference earlier tables in FROM', 'LATERAL JOIN allows subqueries in FROM to reference columns from preceding tables.', 'active'),
('60000000-0000-0000-0000-000000000826', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What is MVCC?', '["Multi-Version Concurrency Control", "Multi-Value Concurrency Control", "Multi-Version Consistency Control", "Multi-Value Consistency Control"]', 'Multi-Version Concurrency Control', 'MVCC allows concurrent access without locking by maintaining multiple versions of data.', 'active'),
('60000000-0000-0000-0000-000000000827', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What are covering indexes?', '["Indexes that contain all required columns", "Composite indexes", "Partial indexes", "Unique indexes"]', 'Indexes that contain all required columns', 'Covering indexes include all columns needed for a query, avoiding table access.', 'active'),
('60000000-0000-0000-0000-000000000828', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What is query plan caching?', '["Reusing execution plans", "Caching query results", "Storing queries", "Plan optimization"]', 'Reusing execution plans', 'Query plan caching stores and reuses execution plans for similar queries.', 'active'),
('60000000-0000-0000-0000-000000000829', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What are partial indexes?', '["Indexes on subset of table", "Partial data indexes", "Conditional indexes", "All of the above"]', 'All of the above', 'Partial indexes index only rows that satisfy a WHERE condition.', 'active'),
('60000000-0000-0000-0000-000000000830', '50000000-0000-0000-0000-000000000058', 'expert', 'code_mcq', 'What does FOR UPDATE do?', '["Locks selected rows", "Updates rows", "Selects for update", "Both A and C"]', 'Both A and C', 'FOR UPDATE locks selected rows for update in transaction.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000831', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What type of database is MongoDB?', '["Document database", "Relational database", "Graph database", "Key-value store"]', 'Document database', 'MongoDB is a document-oriented NoSQL database storing data in BSON format.', 'active'),
('60000000-0000-0000-0000-000000000832', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What is a collection in MongoDB?', '["Group of documents", "Table equivalent", "Database container", "All of the above"]', 'All of the above', 'A collection is a grouping of MongoDB documents, similar to a table in RDBMS.', 'active'),
('60000000-0000-0000-0000-000000000833', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What is BSON?', '["Binary JSON", "Binary representation of JSON", "Extended JSON", "All of the above"]', 'All of the above', 'BSON is Binary JSON, MongoDB''s binary-encoded serialization of JSON-like documents.', 'active'),
('60000000-0000-0000-0000-000000000834', '50000000-0000-0000-0000-000000000059', 'simple', 'code_mcq', 'What does db.collection.find() return?', '["Cursor to documents", "Array of documents", "Document count", "First document"]', 'Cursor to documents', 'find() returns a cursor that can be iterated to access matching documents.', 'active'),
('60000000-0000-0000-0000-000000000835', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What is aggregation in MongoDB?', '["Data processing pipeline", "Data transformation", "Multi-stage processing", "All of the above"]', 'All of the above', 'Aggregation processes data records and returns computed results through a pipeline.', 'active'),
('60000000-0000-0000-0000-000000000836', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What are MongoDB indexes?', '["Performance optimization", "Query acceleration", "Data organization", "All of the above"]', 'All of the above', 'Indexes support efficient query execution by organizing data for quick lookup.', 'active'),
('60000000-0000-0000-0000-000000000837', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What is sharding in MongoDB?', '["Horizontal scaling", "Data partitioning", "Distributed data storage", "All of the above"]', 'All of the above', 'Sharding distributes data across multiple machines for horizontal scaling.', 'active'),
('60000000-0000-0000-0000-000000000838', '50000000-0000-0000-0000-000000000059', 'intermediate', 'code_mcq', 'What does $lookup operator do?', '["Left outer join", "Collection join", "Document join", "All of the above"]', 'All of the above', '$lookup performs a left outer join between two collections.', 'active'),
('60000000-0000-0000-0000-000000000839', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What is a replica set?', '["Group of mongod instances", "High availability setup", "Data redundancy", "All of the above"]', 'All of the above', 'Replica set provides redundancy and high availability through multiple copies of data.', 'active'),
('60000000-0000-0000-0000-000000000840', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What is the oplog?', '["Operations log", "Replication log", "Change stream source", "All of the above"]', 'All of the above', 'The oplog records all operations that modify data for replication purposes.', 'active'),
('60000000-0000-0000-0000-000000000841', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What are change streams?', '["Real-time data change notifications", "Event streams", "Database triggers", "All of the above"]', 'All of the above', 'Change streams allow applications to access real-time data changes.', 'active'),
('60000000-0000-0000-0000-000000000842', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What is MongoDB Atlas?', '["Managed cloud service", "Database as a service", "Multi-cloud database", "All of the above"]', 'All of the above', 'MongoDB Atlas is a fully-managed cloud database service.', 'active'),
('60000000-0000-0000-0000-000000000843', '50000000-0000-0000-0000-000000000059', 'expert', 'code_mcq', 'What does $graphLookup enable?', '["Graph traversal queries", "Recursive lookups", "Hierarchical queries", "All of the above"]', 'All of the above', '$graphLookup performs recursive search on a collection for graph/tree data.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000844', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'What is Redis?', '["In-memory key-value store", "Cache database", "Message broker", "All of the above"]', 'All of the above', 'Redis is an in-memory data structure store used as database, cache, and message broker.', 'active'),
('60000000-0000-0000-0000-000000000845', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'What is Cassandra?', '["Wide-column store", "Distributed database", "NoSQL database", "All of the above"]', 'All of the above', 'Apache Cassandra is a distributed wide-column store NoSQL database.', 'active'),
('60000000-0000-0000-0000-000000000846', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'What is a graph database?', '["Stores nodes and relationships", "Graph-structured data", "Network data", "All of the above"]', 'All of the above', 'Graph databases use graph structures with nodes, edges, and properties.', 'active'),
('60000000-0000-0000-0000-000000000847', '50000000-0000-0000-0000-000000000060', 'simple', 'code_mcq', 'What does SET key value do in Redis?', '["Sets key to hold value", "Creates key-value pair", "Stores data", "All of the above"]', 'All of the above', 'SET stores a key-value pair in Redis with the string value.', 'active'),
('60000000-0000-0000-0000-000000000848', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'What is CAP theorem?', '["Consistency, Availability, Partition tolerance", "Database theorem", "Distributed systems", "All of the above"]', 'All of the above', 'CAP theorem states distributed systems can guarantee only two of three: Consistency, Availability, Partition tolerance.', 'active'),
('60000000-0000-0000-0000-000000000849', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'What is eventual consistency?', '["Consistency achieved over time", "Asynchronous consistency", "Weak consistency", "All of the above"]', 'All of the above', 'Eventual consistency guarantees if no new updates, all accesses return last updated value eventually.', 'active'),
('60000000-0000-0000-0000-000000000850', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'What is a wide-column store?', '["Column-family database", "2D key-value store", "Tabular but flexible", "All of the above"]', 'All of the above', 'Wide-column stores organize data into columns rather than rows for scalability.', 'active'),
('60000000-0000-0000-0000-000000000851', '50000000-0000-0000-0000-000000000060', 'intermediate', 'code_mcq', 'What Cypher query language is used for?', '["Graph database queries", "Neo4j queries", "Pattern matching", "All of the above"]', 'All of the above', 'Cypher is Neo4j''s graph query language for pattern matching in graphs.', 'active'),
('60000000-0000-0000-0000-000000000852', '50000000-0000-0000-0000-000000000060', 'expert', 'mcq', 'What is Bloom filter?', '["Probabilistic data structure", "Space-efficient", "Membership test", "All of the above"]', 'All of the above', 'Bloom filter is probabilistic data structure for testing set membership with possible false positives.', 'active'),
('60000000-0000-0000-0000-000000000853', '50000000-0000-0000-0000-000000000060', 'expert', 'mcq', 'What is gossip protocol?', '["Peer-to-peer communication", "Failure detection", "Membership protocol", "All of the above"]', 'All of the above', 'Gossip protocol disseminates information in decentralized manner, used in distributed databases.', 'active'),
('60000000-0000-0000-0000-000000000854', '50000000-0000-0000-0000-000000000060', 'expert', 'mcq', 'What is vector clock?', '["Conflict detection in distributed systems", "Event ordering", "Causal consistency", "All of the above"]', 'All of the above', 'Vector clocks track causality between events in distributed systems for conflict detection.', 'active'),
('60000000-0000-0000-0000-000000000855', '50000000-0000-0000-0000-000000000060', 'expert', 'mcq', 'What is anti-entropy?', '["Data synchronization process", "Repair protocol", "Consistency maintenance", "All of the above"]', 'All of the above', 'Anti-entropy protocols synchronize data between nodes in distributed databases.', 'active'),
('60000000-0000-0000-0000-000000000856', '50000000-0000-0000-0000-000000000060', 'expert', 'code_mcq', 'What does MERGE do in Cypher?', '["Creates node if doesn''t exist", "Pattern matching with creation", "Upsert operation", "All of the above"]', 'All of the above', 'MERGE ensures a pattern exists in the graph, creating it if missing (upsert).', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000857', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'What is database normalization?', '["Organizing data to reduce redundancy", "Eliminating anomalies", "Improving integrity", "All of the above"]', 'All of the above', 'Normalization organizes data to minimize redundancy and dependency.', 'active'),
('60000000-0000-0000-0000-000000000858', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'What is 1NF (First Normal Form)?', '["Atomic values, no repeating groups", "Basic normalization", "Table structure", "All of the above"]', 'All of the above', '1NF requires atomic values and eliminates repeating groups.', 'active'),
('60000000-0000-0000-0000-000000000859', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'What is a foreign key constraint?', '["Referential integrity", "Links tables", "Enforces relationships", "All of the above"]', 'All of the above', 'Foreign key constraints enforce referential integrity between tables.', 'active'),
('60000000-0000-0000-0000-000000000860', '50000000-0000-0000-0000-000000000061', 'simple', 'code_mcq', 'What does ER diagram represent?', '["Entity-Relationship model", "Database schema", "Data relationships", "All of the above"]', 'All of the above', 'ER diagrams visually represent entities and their relationships.', 'active'),
('60000000-0000-0000-0000-000000000861', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is 2NF (Second Normal Form)?', '["1NF + no partial dependencies", "Full functional dependency", "Key-based", "All of the above"]', 'All of the above', '2NF requires 1NF and eliminates partial dependencies on composite keys.', 'active'),
('60000000-0000-0000-0000-000000000862', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is 3NF (Third Normal Form)?', '["2NF + no transitive dependencies", "Non-key dependency removal", "Further normalization", "All of the above"]', 'All of the above', '3NF requires 2NF and eliminates transitive dependencies.', 'active'),
('60000000-0000-0000-0000-000000000863', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is denormalization?', '["Intentional redundancy", "Performance optimization", "Read optimization", "All of the above"]', 'All of the above', 'Denormalization adds redundancy to improve read performance at cost of write performance.', 'active'),
('60000000-0000-0000-0000-000000000864', '50000000-0000-0000-0000-000000000061', 'intermediate', 'code_mcq', 'What does cardinality in relationships mean?', '["Number of relationships", "One-to-one, one-to-many", "Relationship types", "All of the above"]', 'All of the above', 'Cardinality defines numerical relationships between entities (1:1, 1:M, M:M).', 'active'),
('60000000-0000-0000-0000-000000000865', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What is BCNF (Boyce-Codd Normal Form)?', '["Stricter than 3NF", "Every determinant is candidate key", "Eliminates anomalies", "All of the above"]', 'All of the above', 'BCNF is stronger than 3NF, requiring every determinant to be a candidate key.', 'active'),
('60000000-0000-0000-0000-000000000866', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What are inclusion dependencies?', '["Foreign key generalization", "Referential constraints", "Inter-relational constraints", "All of the above"]', 'All of the above', 'Inclusion dependencies generalize foreign key concept for complex constraints.', 'active'),
('60000000-0000-0000-0000-000000000867', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What is star schema?', '["Data warehouse schema", "Fact and dimension tables", "Denormalized structure", "All of the above"]', 'All of the above', 'Star schema has central fact table connected to dimension tables for data warehousing.', 'active'),
('60000000-0000-0000-0000-000000000868', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What is snowflake schema?', '["Normalized star schema", "Dimension hierarchies", "Space efficient", "All of the above"]', 'All of the above', 'Snowflake schema normalizes dimension tables in star schema.', 'active'),
('60000000-0000-0000-0000-000000000869', '50000000-0000-0000-0000-000000000061', 'expert', 'code_mcq', 'What does UML class diagram show for databases?', '["Classes as tables", "Associations as relationships", "Multiplicity as cardinality", "All of the above"]', 'All of the above', 'UML class diagrams can model database schemas with classes as tables.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000870', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'What does ACID stand for?', '["Atomicity, Consistency, Isolation, Durability", "Availability, Consistency, Isolation, Durability", "Atomicity, Consistency, Integrity, Durability", "Atomicity, Concurrency, Isolation, Durability"]', 'Atomicity, Consistency, Isolation, Durability', 'ACID properties guarantee reliable processing of database transactions.', 'active'),
('60000000-0000-0000-0000-000000000871', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'What is a database transaction?', '["Unit of work", "Sequence of operations", "Atomic operation set", "All of the above"]', 'All of the above', 'Transaction is a logical unit of work that must be atomic, consistent, isolated, durable.', 'active'),
('60000000-0000-0000-0000-000000000872', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'What is atomicity?', '["All or nothing", "Transaction completeness", "No partial updates", "All of the above"]', 'All of the above', 'Atomicity ensures transaction either completes fully or has no effect.', 'active'),
('60000000-0000-0000-0000-000000000873', '50000000-0000-0000-0000-000000000062', 'simple', 'code_mcq', 'What does BEGIN TRANSACTION start?', '["Transaction block", "ACID transaction", "Database transaction", "All of the above"]', 'All of the above', 'BEGIN TRANSACTION marks start of explicit transaction.', 'active'),
('60000000-0000-0000-0000-000000000874', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What are isolation levels?', '["Transaction visibility rules", "Concurrency control", "Read phenomena prevention", "All of the above"]', 'All of the above', 'Isolation levels control visibility of transaction changes to other transactions.', 'active'),
('60000000-0000-0000-0000-000000000875', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What is dirty read?', '["Read uncommitted data", "Isolation anomaly", "Read phenomenon", "All of the above"]', 'All of the above', 'Dirty read occurs when transaction reads data written by uncommitted transaction.', 'active'),
('60000000-0000-0000-0000-000000000876', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What is phantom read?', '["New rows appear", "Isolation anomaly", "Repeatable read issue", "All of the above"]', 'All of the above', 'Phantom read occurs when transaction re-executes query finding new rows.', 'active'),
('60000000-0000-0000-0000-000000000877', '50000000-0000-0000-0000-000000000062', 'intermediate', 'code_mcq', 'What does SAVEPOINT create?', '["Nested transaction point", "Partial rollback point", "Transaction marker", "All of the above"]', 'All of the above', 'SAVEPOINT allows partial rollback within transaction.', 'active'),
('60000000-0000-0000-0000-000000000878', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'What is two-phase locking?', '["Concurrency control protocol", "Lock acquisition protocol", "Deadlock prevention", "All of the above"]', 'All of the above', '2PL protocol has growing phase (acquire locks) and shrinking phase (release locks).', 'active'),
('60000000-0000-0000-0000-000000000879', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'What is deadlock?', '["Circular wait condition", "Transaction blocking", "Resource contention", "All of the above"]', 'All of the above', 'Deadlock occurs when transactions wait for each other''s locks circularly.', 'active'),
('60000000-0000-0000-0000-000000000880', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'What is optimistic concurrency control?', '["Conflict detection at commit", "No locking during transaction", "Version-based", "All of the above"]', 'All of the above', 'Optimistic control assumes few conflicts, detects them at commit time.', 'active'),
('60000000-0000-0000-0000-000000000881', '50000000-0000-0000-0000-000000000062', 'expert', 'code_mcq', 'What does SET TRANSACTION ISOLATION LEVEL SERIALIZABLE do?', '["Highest isolation level", "Prevents all anomalies", "Serial execution equivalent", "All of the above"]', 'All of the above', 'SERIALIZABLE provides strictest isolation, preventing all read phenomena.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000882', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'What is database backup?', '["Data copy for recovery", "Disaster recovery", "Data protection", "All of the above"]', 'All of the above', 'Backups copy database data for restoration in case of data loss.', 'active'),
('60000000-0000-0000-0000-000000000883', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'What is database replication?', '["Copying data to multiple servers", "High availability", "Load distribution", "All of the above"]', 'All of the above', 'Replication copies and maintains database objects across multiple databases.', 'active'),
('60000000-0000-0000-0000-000000000884', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'What is database migration?', '["Moving data between systems", "Schema changes", "Version upgrades", "All of the above"]', 'All of the above', 'Migration involves transferring data between storage types or database systems.', 'active'),
('60000000-0000-0000-0000-000000000885', '50000000-0000-0000-0000-000000000063', 'simple', 'code_mcq', 'What does VACUUM do in PostgreSQL?', '["Reclaims storage", "Removes dead tuples", "Updates statistics", "All of the above"]', 'All of the above', 'VACUUM reclaims storage occupied by dead tuples and updates statistics.', 'active'),
('60000000-0000-0000-0000-000000000886', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is database partitioning?', '["Dividing large tables", "Performance improvement", "Manageability", "All of the above"]', 'All of the above', 'Partitioning divides large tables into smaller, more manageable pieces.', 'active'),
('60000000-0000-0000-0000-000000000887', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is connection pooling?', '["Reusing database connections", "Performance optimization", "Resource management", "All of the above"]', 'All of the above', 'Connection pooling maintains cache of database connections for reuse.', 'active'),
('60000000-0000-0000-0000-000000000888', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is database monitoring?', '["Tracking performance metrics", "Health checking", "Alerting", "All of the above"]', 'All of the above', 'Monitoring tracks database performance, health, and resource usage.', 'active'),
('60000000-0000-0000-0000-000000000889', '50000000-0000-0000-0000-000000000063', 'intermediate', 'code_mcq', 'What does EXPLAIN show?', '["Query execution plan", "Optimizer plan", "Cost estimation", "All of the above"]', 'All of the above', 'EXPLAIN shows how SQL statement would be executed by database.', 'active'),
('60000000-0000-0000-0000-000000000890', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What is query rewriting?', '["Optimizer transformation", "Query simplification", "Performance optimization", "All of the above"]', 'All of the above', 'Query rewriting transforms queries into equivalent but more efficient forms.', 'active'),
('60000000-0000-0000-0000-000000000891', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What is cost-based optimization?', '["Optimizer using statistics", "Cost estimation", "Plan selection", "All of the above"]', 'All of the above', 'Cost-based optimizer estimates cost of different execution plans.', 'active'),
('60000000-0000-0000-0000-000000000892', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What is buffer pool?', '["Memory cache for data pages", "Performance optimization", "Reduces disk I/O", "All of the above"]', 'All of the above', 'Buffer pool caches frequently accessed data pages in memory.', 'active'),
('60000000-0000-0000-0000-000000000893', '50000000-0000-0000-0000-000000000063', 'expert', 'code_mcq', 'What does ANALYZE do in PostgreSQL?', '["Updates statistics", "Helps query optimizer", "Collects table stats", "All of the above"]', 'All of the above', 'ANALYZE collects statistics about table contents for query optimizer.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000894', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What is database encryption?', '["Protecting data at rest", "Data security", "Confidentiality", "All of the above"]', 'All of the above', 'Encryption converts data into unreadable form to protect confidentiality.', 'active'),
('60000000-0000-0000-0000-000000000895', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What are database roles?', '["Permission groups", "Access control", "Security management", "All of the above"]', 'All of the above', 'Roles group permissions and can be assigned to users for access control.', 'active'),
('60000000-0000-0000-0000-000000000896', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What is SQL injection?', '["Code injection attack", "Security vulnerability", "Database attack", "All of the above"]', 'All of the above', 'SQL injection exploits vulnerabilities by injecting malicious SQL code.', 'active'),
('60000000-0000-0000-0000-000000000897', '50000000-0000-0000-0000-000000000064', 'simple', 'code_mcq', 'What does GRANT privilege ON table TO user do?', '["Gives permissions", "Access control", "Security management", "All of the above"]', 'All of the above', 'GRANT gives specific privileges on database objects to users/roles.', 'active'),
('60000000-0000-0000-0000-000000000898', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is database auditing?', '["Tracking database activities", "Security monitoring", "Compliance", "All of the above"]', 'All of the above', 'Auditing records database activities for security and compliance monitoring.', 'active'),
('60000000-0000-0000-0000-000000000899', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is horizontal scaling?', '["Adding more servers", "Scale out", "Distributed architecture", "All of the above"]', 'All of the above', 'Horizontal scaling adds more machines to resource pool (scale out).', 'active'),
('60000000-0000-0000-0000-000000000900', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is vertical scaling?', '["Adding more resources to server", "Scale up", "Hardware upgrade", "All of the above"]', 'All of the above', 'Vertical scaling adds more power to existing machine (scale up).', 'active'),
('60000000-0000-0000-0000-000000000901', '50000000-0000-0000-0000-000000000064', 'intermediate', 'code_mcq', 'What does WITH ENCRYPTION do for stored procedures?', '["Encrypts procedure text", "Hides source code", "Security feature", "All of the above"]', 'All of the above', 'WITH ENCRYPTION encrypts stored procedure definition in system tables.', 'active'),
('60000000-0000-0000-0000-000000000902', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'What is database sharding?', '["Horizontal partitioning across servers", "Data distribution", "Scalability technique", "All of the above"]', 'All of the above', 'Sharding partitions data across multiple databases for horizontal scaling.', 'active'),
('60000000-0000-0000-0000-000000000903', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'What is TLS/SSL for databases?', '["Encrypted connections", "Secure communication", "Transport security", "All of the above"]', 'All of the above', 'TLS/SSL encrypts data in transit between clients and database servers.', 'active'),
('60000000-0000-0000-0000-000000000904', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'What is row-level security?', '["Fine-grained access control", "Row-based permissions", "Data security", "All of the above"]', 'All of the above', 'Row-level security restricts access to specific rows based on user context.', 'active'),
('60000000-0000-0000-0000-000000000905', '50000000-0000-0000-0000-000000000064', 'expert', 'code_mcq', 'What does CREATE POLICY do in PostgreSQL?', '["Defines row-level security", "Access policy", "Security policy", "All of the above"]', 'All of the above', 'CREATE POLICY defines row-level security policies for tables.', 'active');
